    raw = {"ORDER_POLICY": {
        "SPREAD": 0.1, "TRIM_FRACTION": 0.25, "SCALE_UP": 2.0, "SCALE_DOWN": 0.5,
        "STOP_LOSS_PCT": 0.4, "TAKE_PROFIT_PCT": 1.5,
    }}
    p = _load_order_policy(raw)
    assert p.spread == 0.1 and p.trim_fraction == 0.25
    assert p.scale_up == 2.0 and p.scale_down == 0.5
    assert p.stop_loss_pct == 0.4 and p.take_profit_pct == 1.5


