    # Old config.json files only had EXECUTION and no SL/TP.
    raw = {"EXECUTION": {"SPREAD": 0.07, "TRIM_FRACTION": 0.5}}
    p = _load_order_policy(raw)
    assert p.spread == 0.07 and p.trim_fraction == 0.5
    assert p.stop_loss_pct is None and p.take_profit_pct is None  # disabled by default


def test_defaults_when_block_absent():
    p = _load_order_policy({})
    assert p.spread == 0.05 and p.trim_fraction == 0.5
    assert p.stop_loss_pct is None and p.take_profit_pct is None


