    cfg = load_config(base_dir=tmp_path, profile="dev")
    assert cfg.traders["A"].stop_loss_pct == 0.3 and cfg.traders["A"].take_profit_pct == 2.0
    # B has no override -> inherits the global default (None here, resolved by order_policy)
    assert cfg.traders["B"].stop_loss_pct is None
    assert cfg.policy.stop_loss_pct == 0.5

